import{_ as d,o,c as e,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 23 章 平台全景：一支 AI 团队的全套装备","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第五篇 平台能力全景/第 23 章 平台全景：一支 AI 团队的全套装备.md","filePath":"bluebook/第五篇 平台能力全景/第 23 章 平台全景：一支 AI 团队的全套装备.md"}'),a={name:"bluebook/第五篇 平台能力全景/第 23 章 平台全景：一支 AI 团队的全套装备.md"};function c(s,t,l,n,i,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-23-章-平台全景-一支-ai-团队的全套装备" tabindex="-1">第 23 章 平台全景：一支 AI 团队的全套装备 <a class="header-anchor" href="#第-23-章-平台全景-一支-ai-团队的全套装备" aria-label="Permalink to &quot;第 23 章 平台全景：一支 AI 团队的全套装备&quot;">​</a></h1><blockquote><p>本章目标：把&quot;我&quot;背后的装备柜整个打开。你会看到 <strong>7 层结构、33 个内置技能、11 位专家助手、3 套团队模板</strong>，以及它们之间怎么协作。<strong>先知道有什么，才知道能向我要什么。</strong></p></blockquote><h2 id="_23-1-从-一个助手-到-一套装备" tabindex="-1">23.1 从&quot;一个助手&quot;到&quot;一套装备&quot; <a class="header-anchor" href="#_23-1-从-一个助手-到-一套装备" aria-label="Permalink to &quot;23.1 从&quot;一个助手&quot;到&quot;一套装备&quot;&quot;">​</a></h2><p>前面 22 章里，你大多是把我当成&quot;一个很能干的同事&quot;在用：能读文件、能写代码、能查资料、能跑流程。</p><p>但真实的团队里，一个同事能不能干活，从来不只看他本人——</p><ul><li>他手上有没有<strong>工具</strong>？（技能）</li><li>他有没有<strong>专业身份和做事规范</strong>？（专家助手规则）</li><li>他能不能<strong>拉一个小组</strong>一起上？（团队模板）</li><li>他能不能<strong>接上外部系统</strong>？（扩展）</li><li>他能不能<strong>自己按时起床干活</strong>？（定时任务）</li></ul><p>这些在我这里全都存在，而且<strong>大部分默认就装好了</strong>，你不需要安装、不需要配置——你只需要知道它们在哪、什么时候叫谁。</p><p>这些年我见过太多人卡在同一个地方：<strong>不是我不会做，是他不知道该向我要。</strong></p><blockquote><p>一句话：能力是现成的，<strong>认知缺口</strong>才是瓶颈。</p></blockquote><h2 id="_23-2-七层结构-我的装备柜" tabindex="-1">23.2 七层结构：我的装备柜 <a class="header-anchor" href="#_23-2-七层结构-我的装备柜" aria-label="Permalink to &quot;23.2 七层结构：我的装备柜&quot;">​</a></h2><p>我的数据目录里，有七个层次各司其职。你可以理解成一支团队的后勤体系：</p><table tabindex="0"><thead><tr><th>层</th><th>目录</th><th>它是什么</th><th>一句话理解</th></tr></thead><tbody><tr><td>1️⃣ 助手内核</td><td><code>assistant-rules/</code></td><td>不同身份的&quot;人格 + 做事规范&quot;</td><td>决定我<strong>以谁的身份</strong>干活</td></tr><tr><td>2️⃣ 内置技能库</td><td><code>builtin-skills/</code></td><td>平台预装的技能包（当前技能包版本 <code>0.1.33</code>）</td><td>决定我<strong>天生会什么</strong></td></tr><tr><td>3️⃣ 个人技能</td><td><code>skills/</code></td><td>你自己写或装进来的技能</td><td>决定我<strong>为你专精什么</strong></td></tr><tr><td>4️⃣ 团队模板</td><td><code>teams/</code></td><td>预置的角色组合 + 工作流编排</td><td>决定我<strong>能拉出什么队形</strong></td></tr><tr><td>5️⃣ 扩展</td><td><code>extensions/</code></td><td>外接能力包</td><td>决定我<strong>能不能接上外部世界</strong></td></tr><tr><td>6️⃣ 运行时</td><td><code>runtime/</code></td><td>托管工具与 Node 运行时</td><td>决定我的<strong>工具能不能真的跑起来</strong></td></tr><tr><td>7️⃣ 存储与会话</td><td><code>conversations/</code>、<code>projects/</code>、<code>*-sessions/</code></td><td>会话记录、工作区、历史数据库</td><td>决定我<strong>记不记得住、找不找得回</strong></td></tr></tbody></table><p>这里面最容易被忽略的是第 2 层和第 4 层——因为它们<strong>默认就是满的</strong>，没人提醒你去看，于是很多人用了半年，还以为我只会&quot;聊天和写文档&quot;。</p><h2 id="_23-3-三个来源-内置、自建、扩展" tabindex="-1">23.3 三个来源：内置、自建、扩展 <a class="header-anchor" href="#_23-3-三个来源-内置、自建、扩展" aria-label="Permalink to &quot;23.3 三个来源：内置、自建、扩展&quot;">​</a></h2><p>同样是&quot;一个技能&quot;，来源不同，维护方式也不同。搞清楚这个区别，你就知道该去哪找、去哪改。</p><table tabindex="0"><thead><tr><th>来源</th><th>位置</th><th>谁维护</th><th>典型代表</th><th>能不能改</th></tr></thead><tbody><tr><td><strong>内置</strong></td><td><code>builtin-skills/</code></td><td>平台随版本更新</td><td>图像生成、视频生成、Office 文档、PPT、Mermaid</td><td>❌ 不要改，会被覆盖；要用&quot;场景层&quot;扩展</td></tr><tr><td><strong>自建</strong></td><td><code>skills/</code></td><td><strong>你自己</strong></td><td>你的行业方法论、公司规范、固定流程</td><td>✅ 随便改，就是你的资产</td></tr><tr><td><strong>扩展</strong></td><td><code>extensions/</code></td><td>扩展作者</td><td>外部编辑器/工具集成</td><td>⚠️ 按扩展文档升级</td></tr></tbody></table><p>一个常见的误区：<strong>看到内置技能不满足需求，就想直接改内置的 <code>SKILL.md</code>。</strong></p><p>不要这么做。正确做法是二选一：</p><ol><li><strong>写自己的技能</strong> → 放到 <code>skills/</code>，在内置能力之上叠加你的规范（第 17 章讲过怎么蒸馏）；</li><li><strong>用&quot;场景层&quot;扩展</strong> → 内置的 Office 类技能本身就是&quot;基础层 + 场景层&quot;结构，场景层就是留给你加行业规则的。</li></ol><blockquote><p>判断口诀：<strong>平台给的是&quot;通用能力&quot;，你要沉淀的是&quot;你的规矩&quot;。</strong> 规矩永远放自己那层。</p></blockquote><h2 id="_23-4-能力地图-一页看清全部" tabindex="-1">23.4 能力地图：一页看清全部 <a class="header-anchor" href="#_23-4-能力地图-一页看清全部" aria-label="Permalink to &quot;23.4 能力地图：一页看清全部&quot;">​</a></h2><p>下面是当前平台开箱即用的能力全景。这一页建议你截图存下来。</p><h3 id="_23-4-1-生成类-从文字到图、视频" tabindex="-1">23.4.1 生成类：从文字到图、视频 <a class="header-anchor" href="#_23-4-1-生成类-从文字到图、视频" aria-label="Permalink to &quot;23.4.1 生成类：从文字到图、视频&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>技能</th><th>数量</th></tr></thead><tbody><tr><td>🎨 图像生成</td><td>DALL·E 3、FLUX、Midjourney、Stable Diffusion</td><td>4</td></tr><tr><td>🎬 视频生成</td><td>豆包 Seedance（标准 / Fast / Mini）、可灵 Kling、海螺 MiniMax、Runway、Sora</td><td>7</td></tr></tbody></table><h3 id="_23-4-2-交付类-从内容到文件" tabindex="-1">23.4.2 交付类：从内容到文件 <a class="header-anchor" href="#_23-4-2-交付类-从内容到文件" aria-label="Permalink to &quot;23.4.2 交付类：从内容到文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>技能</th><th>数量</th></tr></thead><tbody><tr><td>📄 Word 文档</td><td><code>officecli-docx</code>（标准文档）、<code>officecli-word-form</code>（表单/公文格式）</td><td>2</td></tr><tr><td>📊 表格</td><td><code>officecli-xlsx</code></td><td>1</td></tr><tr><td>📽️ 演示文稿</td><td><code>officecli-pptx</code>、<code>morph-ppt</code>、<code>morph-ppt-3d</code></td><td>3</td></tr><tr><td>🎓 专业文档</td><td><code>officecli-academic-paper</code>（论文）、<code>officecli-pitch-deck</code>（路演）、<code>officecli-financial-model</code>（财务模型）、<code>officecli-data-dashboard</code>（数据看板）</td><td>4</td></tr><tr><td>📐 图表</td><td><code>mermaid</code>（流程图/时序图/甘特图）</td><td>1</td></tr><tr><td>📎 PDF</td><td><code>pdf</code>（读取、解析、生成）</td><td>1</td></tr></tbody></table><h3 id="_23-4-3-自动化与集成类" tabindex="-1">23.4.3 自动化与集成类 <a class="header-anchor" href="#_23-4-3-自动化与集成类" aria-label="Permalink to &quot;23.4.3 自动化与集成类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>技能</th><th>作用</th></tr></thead><tbody><tr><td>⏰ 定时任务</td><td><code>cron</code></td><td>让我按计划自己开工</td></tr><tr><td>🧠 技能自举</td><td><code>skill-creator</code>、<code>momawork-skills</code></td><td>教我怎么造技能、管技能</td></tr><tr><td>⚡ 能力增强</td><td><code>superpowers</code></td><td>让内置能力发挥得更充分</td></tr><tr><td>💬 消息投递</td><td><code>weixin-file-send</code></td><td>把产出直接发到微信</td></tr><tr><td>📱 内容平台</td><td><code>xiaohongshu-recruiter</code>、<code>x-recruiter</code></td><td>小红书 / X 平台的运营与检索</td></tr><tr><td>🐣 环境引导</td><td><code>moma-setup-guide</code>、<code>momawork-webui-setup</code>、<code>openclaw-setup</code>、<code>star-office-helper</code></td><td>装好、接通、跑起来</td></tr><tr><td>🎭 其他</td><td><code>moltbook</code>、<code>story-roleplay</code></td><td>创作与互动类玩法</td></tr></tbody></table><blockquote><p>注意：上面的 <code>cron</code>、<code>skill-creator</code>、<code>officecli</code>、<code>superpowers</code>、<code>momawork-skills</code> 属于<strong>自动注入层</strong>（<code>auto-inject</code>）——它们不需要你手动加载，平台会在合适的场景自动挂上去。这解释了一个常见困惑：<em>&quot;我没装定时任务技能，为什么它能定时？&quot;</em></p></blockquote><h2 id="_23-5-版本与更新-装备是怎么长出来的" tabindex="-1">23.5 版本与更新：装备是怎么长出来的 <a class="header-anchor" href="#_23-5-版本与更新-装备是怎么长出来的" aria-label="Permalink to &quot;23.5 版本与更新：装备是怎么长出来的&quot;">​</a></h2><p>平台的能力不是一次性给的，而是<strong>随版本迭代长出来的</strong>：</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>你能看到的</th></tr></thead><tbody><tr><td>技能包版本</td><td>内置技能库的整体版本号</td><td>当前为 <code>0.1.33</code></td></tr><tr><td>技能粒度</td><td>每个技能独立演进</td><td>新增/替换单个技能不影响其他</td></tr><tr><td>团队模板</td><td>与技能同期更新</td><td>新增模板会自动出现在模板列表里</td></tr><tr><td>扩展</td><td>独立升级</td><td>按扩展自己的节奏</td></tr></tbody></table><p><strong>这对你意味着什么？</strong></p><ol><li><strong>不用担心&quot;我是不是版本落后&quot;</strong>——技能包会随平台更新；</li><li><strong>要担心的是&quot;我的自建层有没有跟上&quot;</strong>——平台能力升级后，你自己的 Skill 可能该更新了；</li><li><strong>升级后建议重读本篇</strong> —— 每次技能包更新，能力地图都会变。</li></ol><h2 id="_23-6-决策表-有需求时-先问哪一层" tabindex="-1">23.6 决策表：有需求时，先问哪一层 <a class="header-anchor" href="#_23-6-决策表-有需求时-先问哪一层" aria-label="Permalink to &quot;23.6 决策表：有需求时，先问哪一层&quot;">​</a></h2><p>这是本章最实用的一张表。遇到需求时，从上往下问自己：</p><table tabindex="0"><thead><tr><th>你的需求</th><th>先看哪一层</th><th>具体入口</th></tr></thead><tbody><tr><td>&quot;要一张图 / 一段视频&quot;</td><td>内置技能库</td><td>第 24 章</td></tr><tr><td>&quot;要一份 Word / Excel / PPT / PDF&quot;</td><td>内置技能库</td><td>第 25 章</td></tr><tr><td>&quot;要更好看的 PPT / 数据看板&quot;</td><td>内置技能库（场景层）</td><td>第 25 章</td></tr><tr><td>&quot;要让某个角色来干&quot;</td><td>助手内核</td><td>第 26 章</td></tr><tr><td>&quot;要一队人协作跑流程&quot;</td><td>团队模板</td><td>第 27 章</td></tr><tr><td>&quot;要接微信 / 外部平台&quot;</td><td>扩展 + 集成类技能</td><td>第 28 章</td></tr><tr><td>&quot;要它每天自己干&quot;</td><td>定时任务</td><td>第 28 章</td></tr><tr><td>&quot;要手机上看 / 远程用&quot;</td><td>WebUI</td><td>第 28 章</td></tr><tr><td>&quot;要沉淀我自己的方法论&quot;</td><td>个人技能</td><td>第 17 章 + <code>skills/</code></td></tr></tbody></table><blockquote><p>使用顺序建议：<strong>先用内置的，再改自建的，最后才考虑扩展。</strong> 从便宜到贵，从快到慢。</p></blockquote><h2 id="_23-7-本章练习" tabindex="-1">23.7 本章练习 <a class="header-anchor" href="#_23-7-本章练习" aria-label="Permalink to &quot;23.7 本章练习&quot;">​</a></h2><ol><li><strong>对照能力地图做一次盘点</strong>：把 23.4 三张表过一遍，圈出你<strong>从来没用过</strong>的能力，写下 3 个你明天就能用的场景。</li><li><strong>找到你的缺口</strong>：上面决策表里，有没有哪一行你答不上来？那就是你最该补的认知。</li><li><strong>检查你的自建层</strong>：你的 <code>skills/</code> 里现在有几个技能？它们分别解决了什么重复劳动？</li></ol><hr><blockquote><p>小结：我不是一个&quot;聊天窗口&quot;，而是一支装备齐全的团队——<strong>33 个技能是手，11 位专家是身份，3 套模板是队形，扩展是外接线路，定时任务是闹钟，存储是记性</strong>。接下来五章，我们一层一层拆开看。</p></blockquote>',42)])])}const b=d(a,[["render",c]]);export{q as __pageData,b as default};
